/* Generated by Vite; caches public game assets only. Never Supabase/auth/API. */
const BUILD = __BUILD_ID__;
const ASSETS = __ASSET_PATHS__;
const APP_CACHE = 'bc26-public-app-' + BUILD;
const GEO_CACHE = 'bc26-public-geodata-v1';
const GEO_LIMIT = 4;
const GEO_BUDGET = 6_000_000;
const META_PATHS = ['manifest.json', 'catalog.json', 'boundaries.geojson', 'archipelagos.json'];
let cacheQueue = Promise.resolve();
self.addEventListener('install', event => {
  event.waitUntil(caches.open(APP_CACHE).then(cache => cache.addAll(ASSETS)));
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith('bc26-public-app-') && key !== APP_CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});
function geoFile(url) {
  const match = url.pathname.match(/^\/geodata\/vn-20261008\/([^/]+)$/);
  return match && (META_PATHS.includes(match[1]) || /^\d{2}-(start|island|coast)\.json$/.test(match[1])) ? match[1] : null;
}
async function retainGeo(request, response, file) {
  const payload = await response.arrayBuffer();
  if (payload.byteLength > (file === 'boundaries.geojson' ? 2_000_000 : 1_000_000)) return;
  const cache = await caches.open(GEO_CACHE);
  await cache.delete(request);
  await cache.put(request, new Response(payload, {status:200, headers:response.headers}));
  const regions = (await cache.keys()).filter(r => !META_PATHS.includes(new URL(r.url).pathname.split('/').at(-1)));
  while (regions.length > GEO_LIMIT) await cache.delete(regions.shift());
  let total = 0;
  for (const key of await cache.keys()) total += (await (await cache.match(key)).arrayBuffer()).byteLength;
  while (total > GEO_BUDGET && regions.length) {
    const key = regions.shift(); total -= (await (await cache.match(key)).arrayBuffer()).byteLength; await cache.delete(key);
  }
}
self.addEventListener('fetch', event => {
  const request = event.request, url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin || request.headers.has('authorization') || url.search) return;
  const file = geoFile(url);
  if (file) {
    event.respondWith((async () => {
      try {
        const response = await fetch(request);
        if (response.ok) {
          const copy = response.clone();
          cacheQueue = cacheQueue.catch(() => {}).then(() => retainGeo(request, copy, file));
          event.waitUntil(cacheQueue);
          return response;
        }
        const saved = await (await caches.open(GEO_CACHE)).match(request);
        return saved || response;
      } catch (error) {
        const saved = await (await caches.open(GEO_CACHE)).match(request);
        if (saved) return saved;
        return new Response('Khu địa hình chưa có dữ liệu offline.', {status:503});
      }
    })());
    return;
  }
  const isGameNavigation = request.mode === 'navigate' && ['/', '/index.html', '/benchmark.html'].includes(url.pathname);
  if (!isGameNavigation && !ASSETS.includes(url.pathname)) return;
  event.respondWith((async () => {
    const cache = await caches.open(APP_CACHE);
    if (isGameNavigation) {
      try {const response = await fetch(request);if (response.ok) return response;} catch {}
      return await cache.match(url.pathname === '/benchmark.html' ? '/benchmark.html' : '/index.html') || new Response('Chưa tải game để dùng offline.', {status:503});
    }
    return await cache.match(url.pathname) || fetch(request);
  })());
});
